cd /tmp/adss-check && python3 - <<'EOF'
import re, pathlib, yaml
names=set()
for p in pathlib.Path('das/contracts').glob('*.yaml'):
    d=yaml.safe_load(p.read_text()); names.add(p.stem)
    names.add(str(d['endpoints']['source'].get('entity','')).lower())
    for c in d['schema']['columns']: names.add(c['target_name'])
for p in list(pathlib.Path('dab').rglob('*.yaml')):
    t=p.read_text()
    for m in re.finditer(r'\b(?:id|name|entity_id|table):\s*"?([A-Za-z_][\w.]*)"?', t): names.add(m.group(1).lower())
    for m in re.finditer(r'transformation_expression:\s*([^\n,}]+)', t): 
        for w in re.findall(r'[a-z_]{3,}', m.group(1)): names.add(w)
names={n.lower().replace('das__staged.','') for n in names if n and len(n)>3}
# machinery/neutral terms that are not business words
names-=set('''adss default_mapping_group extracted_at cast varchar concat date_diff true false name null string'''.split())
print(sorted(names))
print("=== hits in src/ and tests/ ===")
for f in sorted(list(pathlib.Path('src').rglob('*.py'))+list(pathlib.Path('tests').rglob('*.py'))):
    for i,line in enumerate(f.read_text().splitlines(),1):
        for n in names:
            if re.search(r'\b'+re.escape(n)+r'\b', line, re.I):
                print(f"{n:22} {f}:{i}: {line.strip()[:100]}")
EOF
